import { ref } from 'vue'

/**
 * A copy button's state: copy(text) writes the clipboard, and copied is true for 1.5s after. Where the Clipboard API is
 * refused (a browser or a frame that denies it), the older copy command still works inside the click. Only if both are
 * refused does it answer false, and the text stays selectable.
 */
export function useCopy(ms = 1500) {
  const copied = ref(false)
  let timer: ReturnType<typeof setTimeout> | undefined
  async function copy(text: string): Promise<boolean> {
    try {
      await navigator.clipboard.writeText(text)
    }
    catch {
      if (!copyByCommand(text)) return false
    }
    copied.value = true
    clearTimeout(timer)
    // ds-latency: the Copied label stays 1.5s after the copy, which has already happened.
    timer = setTimeout(() => { copied.value = false }, ms)
    return true
  }
  return { copied, copy }
}

// The older way: select the text in an unseen field, run the copy command, hand focus back.
function copyByCommand(text: string) {
  const back = document.activeElement as HTMLElement | null
  const field = document.createElement('textarea')
  field.value = text
  field.setAttribute('readonly', '')
  field.style.position = 'fixed'
  field.style.opacity = '0'
  document.body.appendChild(field)
  field.select()
  let ok = false
  try { ok = document.execCommand('copy') }
  catch { ok = false }
  field.remove()
  back?.focus()
  return ok
}

'use client'
import { useState } from 'react'
import { Check, Link2, Plus, RotateCw } from 'lucide-react'
import { AccuracyAdd } from '@/react/components/product/AccuracyAdd'
import { AccuracyAtWork } from '@/react/components/product/AccuracyAtWork'
import type { AccuracyRow, AccuracyView } from '@/react/components/product/AccuracyDetail'
import { AccuracyOpens } from '@/react/components/product/AccuracyOpens'
import { AccuracySheet } from '@/react/components/product/AccuracySheet'
import { AccuracyTwo } from '@/react/components/product/AccuracyTwo'
import { AccuracyVerdict } from '@/react/components/product/AccuracyVerdict'
import { Button } from '@/react/components/ui/Button'
import { PixelButton } from '@/react/components/ui/PixelButton'
import { Tabs } from '@/react/components/ui/Tabs'
import { useCopy } from '@/react/hooks/useCopy'
import { useControllable } from '@/react/hooks/useControllable'

// Accuracy, Performance's second view (accuracy/Panel.vue): a team's own questions and whether Conare reached the
// right page. The bar holds Performance's two views and the test's actions: Add questions (opening in place; the
// question sheet takes them in its first row instead), Copy link, and Run again as the page's one dark button. Under it,
// one of the four views: 4 "Test at work" ships; 1 "Verdict first", 2 "Two searches" and 3 "Question sheet" are the
// takes beside it. The app owns the test: it answers `onRun`, `onAdd`, `onFix`, `onSearch`, `onRemove` and the tab (`tab` with
// `onTabChange`, Vue's v-model:tab).
type Tab = 'searches' | 'accuracy'
export interface AccuracyPanelProps {
  view: AccuracyView
  version?: 1 | 2 | 3 | 4
  link?: string
  asked?: string[]
  busy?: boolean
  tab?: Tab
  defaultTab?: Tab
  onTabChange?: (tab: Tab) => void
  onRun?: () => void
  onAdd?: (questions: string[]) => void
  onFix?: (row: AccuracyRow) => void
  onSearch?: (row: AccuracyRow) => void
  onRemove?: (row: AccuracyRow) => void
}

export function AccuracyPanel({ view, version = 4, link = '', asked = [], busy, tab: tabValue, defaultTab = 'accuracy', onTabChange, onRun, onAdd, onFix, onSearch, onRemove }: AccuracyPanelProps) {
  const [tab, setTab] = useControllable(tabValue, defaultTab, onTabChange)
  const [adding, setAdding] = useState(false)
  const { copied, copy } = useCopy()
  function more(questions: string[]) {
    setAdding(false)
    onAdd?.(questions)
    onRun?.()
  }
  const pass = { onFix, onSearch, onRemove }
  return (
    <>
      <div data-ds="accuracy-panel" className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
        <Tabs value={tab} onValueChange={setTab} options={[{ value: 'searches', label: 'Searches' }, { value: 'accuracy', label: 'Accuracy' }]} label="performance" />
        <div className="flex flex-wrap items-center gap-2">
          {version !== 3 && <Button press aria-expanded={adding} onClick={() => setAdding(a => !a)}><Plus size={12} strokeWidth={1.5} aria-hidden="true" />Add questions</Button>}
          <Button press onClick={() => copy(link)}>
            {copied ? <Check size={12} strokeWidth={2} aria-hidden="true" /> : <Link2 size={12} strokeWidth={1.5} aria-hidden="true" />}{copied ? 'Link copied' : 'Copy link'}
          </Button>
          <PixelButton disabled={view.state === 'running' || busy} onClick={() => onRun?.()}>
            <RotateCw size={12} strokeWidth={1.5} aria-hidden="true" />{view.state === 'running' ? 'Running' : 'Run again'}
          </PixelButton>
        </div>
      </div>
      <AccuracyOpens data-ds="accuracy-panel" open={adding && version !== 3}><AccuracyAdd asked={asked} onAdd={more} onClose={() => setAdding(false)} /></AccuracyOpens>
      {version === 1
        ? <AccuracyVerdict view={view} {...pass} />
        : version === 2
          ? <AccuracyTwo view={view} {...pass} />
          : version === 3
            ? <AccuracySheet view={view} {...pass} onAdd={q => onAdd?.(q)} />
            : <AccuracyAtWork view={view} {...pass} />}
    </>
  )
}

export default AccuracyPanel

'use client'
import { useRef, useState } from 'react'
import { FileUp, X } from 'lucide-react'
import { Button } from '@/react/components/ui/Button'
import { PixelButton } from '@/react/components/ui/PixelButton'

// More questions, opened in place (accuracy/Add.vue), on the paper in a hairline. Three ways in: paste a list (one a
// line), upload a CSV (its first column), or take what agents already ask, which needs no typing and is the truest
// test. Adding runs them, since a question only helps answered: `onAdd` gets the questions, `onClose` the close button.
export interface AccuracyAddProps {
  asked?: string[]
  onAdd?: (questions: string[]) => void
  onClose?: () => void
}

const count = (n: number) => `${n} ${n === 1 ? 'question' : 'questions'}`

export function AccuracyAdd({ asked = [], onAdd, onClose }: AccuracyAddProps) {
  const [text, setText] = useState('')
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean)
  const input = useRef<HTMLInputElement | null>(null)
  async function file(list: FileList | null) {
    const f = list?.[0]
    if (!f) return
    setText((await f.text()).split('\n').map(l => l.split(',')[0]!.replace(/^"|"$/g, '').trim()).filter(Boolean).join('\n'))
  }
  return (
    <>
      <style href="ds-accuracy-add" precedence="ds">{css}</style>
      <section data-ds="accuracy-add" className="grid grid-cols-[minmax(0,1fr)_minmax(0,320px)] gap-6 border border-edge bg-surface-subtle p-4 max-lg:grid-cols-1" aria-label="add questions">
        <div className="min-w-0 flex-1">
          <label className="sr-only" htmlFor="eval-more">questions, one a line</label>
          <textarea id="eval-more" value={text} onChange={e => setText(e.target.value)} className="block w-full resize-y border border-edge-strong bg-surface p-3 text-ui outline-none transition-[border-color] duration-120 ease-standard placeholder:text-fg-muted focus:border-edge-focus max-md:text-input" rows={5} placeholder="One question a line" />
          <div className="mt-2 flex flex-wrap items-center gap-2">
            <PixelButton disabled={!lines.length} onClick={() => onAdd?.(lines)}>{lines.length ? `Add ${count(lines.length)} and run` : 'Add and run'}</PixelButton>
            <Button press onClick={() => input.current?.click()}><FileUp size={12} strokeWidth={1.5} aria-hidden="true" />Upload a CSV</Button>
            <input ref={input} type="file" accept=".csv,.txt" className="sr-only" tabIndex={-1} aria-label="choose a CSV of questions" onChange={e => void file(e.target.files)} />
            <Button variant="ghost" icon press className="ml-auto" aria-label="close" onClick={() => onClose?.()}><X size={14} strokeWidth={1.5} /></Button>
          </div>
        </div>
        {asked.length > 0 && (
          <div>
            <p className="mb-1 type-meta text-fg-muted">What your agents ask most</p>
            {asked.map(q => <button key={q} type="button" className="ds-askedq" onClick={() => setText(text ? text + '\n' + q : q)}>{q}</button>)}
          </div>
        )}
      </section>
    </>
  )
}

export default AccuracyAdd

const css = `
.ds-askedq { display: block; width: 100%; overflow: hidden; padding: 6px 4px; border-top: var(--ds-border-hairline) solid var(--ds-color-edge); text-align: left; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-askedq:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: -2px; }
.ds-askedq:active { background: color-mix(in srgb, var(--ds-color-fg) 8%, var(--ds-color-surface-subtle)); }
@media (hover: hover) and (pointer: fine) { .ds-askedq:hover { background: color-mix(in srgb, var(--ds-color-fg) 5%, var(--ds-color-surface-subtle)); } }
@media (pointer: coarse), (max-width: 767px) { .ds-askedq { min-height: 40px; } }
`

'use client'
import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * A copy button's state: copy(text) writes the clipboard, and copied is true for 1.5s after. Where the Clipboard API is
 * refused (a browser or a frame that denies it), the older copy command still works inside the click. Only if both are
 * refused does it answer false, and the text stays selectable.
 */
export function useCopy(ms = 1500) {
  const [copied, setCopied] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  const copy = useCallback(async (text: string): Promise<boolean> => {
    try {
      await navigator.clipboard.writeText(text)
    }
    catch {
      if (!copyByCommand(text)) return false
    }
    setCopied(true)
    clearTimeout(timer.current)
    // ds-latency: the Copied label stays 1.5s after the copy, which has already happened.
    timer.current = setTimeout(() => setCopied(false), ms)
    return true
  }, [ms])
  return { copied, copy }
}

// The older way: select the text in an unseen field, run the copy command, hand focus back.
function copyByCommand(text: string) {
  const back = document.activeElement as HTMLElement | null
  const field = document.createElement('textarea')
  field.value = text
  field.setAttribute('readonly', '')
  field.style.position = 'fixed'
  field.style.opacity = '0'
  document.body.appendChild(field)
  field.select()
  let ok = false
  try { ok = document.execCommand('copy') }
  catch { ok = false }
  field.remove()
  back?.focus()
  return ok
}

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}

